{
  "name": "INHECO堆叠式孵育振荡器",
  "name_en": "INHECO Incubator Shaker Stack",
  "manufacturer": "INHECO",
  "description": "这是一种可堆叠的实验室孵育振荡设备，用于微孔板等样品载具的控温孵育与振荡混匀。设备具有装载抽屉或托盘、温度控制和二维振荡功能，适用于细胞培养、样品孵育、反应混匀及自动化工作站中的板式处理流程。",
  "description_en": "A stackable laboratory incubator shaker for temperature-controlled incubation and shaking of microplates and similar sample carriers. It includes a loading drawer or tray, temperature regulation, and two-axis shaking, and is used for cell culture, sample incubation, reaction mixing, and plate-based workflows in automated lab systems.",
  "tag_hints": [
    "incubator shaker",
    "microplate incubation",
    "temperature control",
    "orbital shaking",
    "stacked laboratory module",
    "loading drawer",
    "sample mixing",
    "cell culture"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭培养箱门并将装载托盘送回设备内。",
      "description_en": "Close the incubator door and retract the loading tray into the device."
    },
    {
      "action_name": "auto-delete_counter",
      "description": "重置指定计数器。",
      "description_en": "Reset a specified counter."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化指定堆叠单元，使其准备好执行后续操作。",
      "description_en": "Initialize the specified stack unit so it is ready for subsequent operations."
    },
    {
      "action_name": "auto-is_shaking_enabled",
      "description": "查询振荡功能是否已启用。",
      "description_en": "Query whether shaking is enabled."
    },
    {
      "action_name": "auto-is_temperature_control_enabled",
      "description": "查询温度控制是否已启用。",
      "description_en": "Query whether temperature control is enabled."
    },
    {
      "action_name": "auto-open",
      "description": "打开培养箱门并将装载托盘推出。",
      "description_en": "Open the incubator door and extend the loading tray."
    },
    {
      "action_name": "auto-perform_self_test",
      "description": "执行设备内部自检。",
      "description_en": "Perform the device's internal self-test."
    },
    {
      "action_name": "auto-read_whole_shaker_calibration_data",
      "description": "读取完整的振荡器校准数据。",
      "description_en": "Read the complete shaker calibration data."
    },
    {
      "action_name": "auto-request_calibration_high",
      "description": "查询高点校准数据。",
      "description_en": "Query the high-point calibration data."
    },
    {
      "action_name": "auto-request_calibration_low",
      "description": "查询低点校准数据。",
      "description_en": "Query the low-point calibration data."
    },
    {
      "action_name": "auto-request_delta_temperature",
      "description": "查询目标温度与实际板温之间的温差。",
      "description_en": "Query the temperature difference between the target and the actual plate temperature."
    },
    {
      "action_name": "auto-request_drawer_cycles_performed",
      "description": "查询装载抽屉已执行的开合循环次数。",
      "description_en": "Query how many drawer open/close cycles have been performed."
    },
    {
      "action_name": "auto-request_drawer_status",
      "description": "查询装载抽屉当前状态。",
      "description_en": "Query the current status of the loading drawer."
    },
    {
      "action_name": "auto-request_firmware_version",
      "description": "查询设备固件版本。",
      "description_en": "Query the device firmware version."
    },
    {
      "action_name": "auto-request_incubator_type",
      "description": "查询孵育振荡器的配置类型。",
      "description_en": "Query the incubator-shaker configuration type."
    },
    {
      "action_name": "auto-request_is_initialized",
      "description": "查询设备是否已初始化。",
      "description_en": "Query whether the device has been initialized."
    },
    {
      "action_name": "auto-request_labware_detection_threshold",
      "description": "查询耗材检测阈值。",
      "description_en": "Query the labware detection threshold."
    },
    {
      "action_name": "auto-request_last_calibration_date",
      "description": "查询最近一次校准日期。",
      "description_en": "Query the date of the last calibration."
    },
    {
      "action_name": "auto-request_machine_allocation",
      "description": "查询指定层中哪些设备槽位已被占用。",
      "description_en": "Query which device slots are occupied on a specified layer."
    },
    {
      "action_name": "auto-request_maximum_allowed_temperature",
      "description": "查询允许的最高温度或记录到的最高设备温度。",
      "description_en": "Query the maximum allowed temperature or the maximum recorded device temperature."
    },
    {
      "action_name": "auto-request_motor_current_limit_anticlockwise",
      "description": "查询逆时针方向电机电流限制。",
      "description_en": "Query the motor current limit for anticlockwise motion."
    },
    {
      "action_name": "auto-request_motor_current_limit_clockwise",
      "description": "查询顺时针方向电机电流限制。",
      "description_en": "Query the motor current limit for clockwise motion."
    },
    {
      "action_name": "auto-request_motor_power_anticlockwise",
      "description": "查询逆时针方向电机功率设置。",
      "description_en": "Query the motor power setting for anticlockwise motion."
    },
    {
      "action_name": "auto-request_motor_power_clockwise",
      "description": "查询顺时针方向电机功率设置。",
      "description_en": "Query the motor power setting for clockwise motion."
    },
    {
      "action_name": "auto-request_number_of_connected_machines",
      "description": "查询指定层已连接的设备数量。",
      "description_en": "Query the number of connected devices on a specified layer."
    },
    {
      "action_name": "auto-request_operation_time_in_hours",
      "description": "查询设备累计运行时间（小时）。",
      "description_en": "Query the device operating time in hours."
    },
    {
      "action_name": "auto-request_pid_controller_coefficients",
      "description": "查询温度控制PID系数。",
      "description_en": "Query the PID coefficients used for temperature control."
    },
    {
      "action_name": "auto-request_plate_in_incubator",
      "description": "查询培养箱内是否检测到板。",
      "description_en": "Query whether a plate is detected inside the incubator."
    },
    {
      "action_name": "auto-request_plate_status_known",
      "description": "查询板存在状态是否已知。",
      "description_en": "Query whether the plate presence status is known."
    },
    {
      "action_name": "auto-request_proportionality_factor",
      "description": "查询比例因子。",
      "description_en": "Query the proportionality factor."
    },
    {
      "action_name": "auto-request_serial_number",
      "description": "查询设备序列号。",
      "description_en": "Query the device serial number."
    },
    {
      "action_name": "auto-request_shaker_amplitude_x",
      "description": "查询X方向振荡幅度。",
      "description_en": "Query the shaker amplitude in the X direction."
    },
    {
      "action_name": "auto-request_shaker_amplitude_y",
      "description": "查询Y方向振荡幅度。",
      "description_en": "Query the shaker amplitude in the Y direction."
    },
    {
      "action_name": "auto-request_shaker_calibration_value",
      "description": "查询指定位置的振荡校准值。",
      "description_en": "Query the shaker calibration value for a specified position."
    },
    {
      "action_name": "auto-request_shaker_frequency_x",
      "description": "查询X方向振荡频率。",
      "description_en": "Query the shaker frequency in the X direction."
    },
    {
      "action_name": "auto-request_shaker_frequency_y",
      "description": "查询Y方向振荡频率。",
      "description_en": "Query the shaker frequency in the Y direction."
    },
    {
      "action_name": "auto-request_shaker_phase_shift",
      "description": "查询X与Y驱动之间的相位差。",
      "description_en": "Query the phase shift between the X and Y shaker drives."
    },
    {
      "action_name": "auto-request_target_temperature",
      "description": "查询目标温度。",
      "description_en": "Query the target temperature."
    },
    {
      "action_name": "auto-request_thermal_calibration_date",
      "description": "查询最近一次热校准日期。",
      "description_en": "Query the date of the last thermal calibration."
    },
    {
      "action_name": "auto-request_whole_calibration_data",
      "description": "查询完整校准数据。",
      "description_en": "Query the complete calibration data."
    },
    {
      "action_name": "auto-reset_calibration_data",
      "description": "重置校准数据。",
      "description_en": "Reset the calibration data."
    },
    {
      "action_name": "auto-send_command",
      "description": "向指定堆叠单元发送设备命令并读取响应。",
      "description_en": "Send a device command to a specified stack unit and read the response."
    },
    {
      "action_name": "auto-set_boost_offset",
      "description": "设置温度提升偏移量。",
      "description_en": "Set the temperature boost offset."
    },
    {
      "action_name": "auto-set_boost_time",
      "description": "设置温度提升时间。",
      "description_en": "Set the temperature boost time."
    },
    {
      "action_name": "auto-set_calibration_high",
      "description": "设置高点校准数据。",
      "description_en": "Set the high-point calibration data."
    },
    {
      "action_name": "auto-set_calibration_low",
      "description": "设置低点校准数据。",
      "description_en": "Set the low-point calibration data."
    },
    {
      "action_name": "auto-set_cooldown_time_factor",
      "description": "设置降温时间因子。",
      "description_en": "Set the cooldown time factor."
    },
    {
      "action_name": "auto-set_heatup_offset",
      "description": "设置升温偏移量。",
      "description_en": "Set the heat-up offset."
    },
    {
      "action_name": "auto-set_heatup_time_factor",
      "description": "设置升温时间因子。",
      "description_en": "Set the heat-up time factor."
    },
    {
      "action_name": "auto-set_max_allowed_device_temperature",
      "description": "设置设备允许的最高温度。",
      "description_en": "Set the maximum allowed device temperature."
    },
    {
      "action_name": "auto-set_motor_current_limit_anticlockwise",
      "description": "设置逆时针方向电机电流限制。",
      "description_en": "Set the motor current limit for anticlockwise motion."
    },
    {
      "action_name": "auto-set_motor_current_limit_clockwise",
      "description": "设置顺时针方向电机电流限制。",
      "description_en": "Set the motor current limit for clockwise motion."
    },
    {
      "action_name": "auto-set_motor_power_anticlockwise",
      "description": "设置逆时针方向电机功率。",
      "description_en": "Set the motor power for anticlockwise motion."
    },
    {
      "action_name": "auto-set_motor_power_clockwise",
      "description": "设置顺时针方向电机功率。",
      "description_en": "Set the motor power for clockwise motion."
    },
    {
      "action_name": "auto-set_pid_integration_value",
      "description": "设置PID积分参数。",
      "description_en": "Set the PID integration value."
    },
    {
      "action_name": "auto-set_pid_proportional_gain",
      "description": "设置PID比例增益。",
      "description_en": "Set the PID proportional gain."
    },
    {
      "action_name": "auto-set_proportionality_factor",
      "description": "设置比例因子。",
      "description_en": "Set the proportionality factor."
    },
    {
      "action_name": "auto-set_shaker_calibration_value",
      "description": "设置指定位置的振荡校准值。",
      "description_en": "Set the shaker calibration value for a specified position."
    },
    {
      "action_name": "auto-set_shaker_parameters",
      "description": "设置X/Y轴振荡幅度、频率和相位参数。",
      "description_en": "Set shaker amplitude, frequency, and phase parameters for the X and Y axes."
    },
    {
      "action_name": "auto-set_shaker_pattern",
      "description": "设置振荡运动模式及其参数。",
      "description_en": "Set the shaking motion pattern and its parameters."
    },
    {
      "action_name": "auto-set_shaker_status",
      "description": "启用或禁用振荡功能。",
      "description_en": "Enable or disable shaking."
    },
    {
      "action_name": "auto-setup",
      "description": "检测并连接孵育振荡器堆叠系统。",
      "description_en": "Detect and connect to the incubator shaker stack system."
    },
    {
      "action_name": "auto-shake",
      "description": "配置振荡参数并开始振荡。",
      "description_en": "Configure shaking parameters and start shaking."
    },
    {
      "action_name": "auto-start_temperature_control",
      "description": "设定目标温度并启动温度控制。",
      "description_en": "Set the target temperature and start temperature control."
    },
    {
      "action_name": "auto-stop",
      "description": "停止所有活动单元并断开设备连接。",
      "description_en": "Stop all active units and disconnect the device."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-stop_temperature_control",
      "description": "停止主动温度控制。",
      "description_en": "Stop active temperature control."
    },
    {
      "action_name": "auto-wait_for_temperature",
      "description": "等待设备温度达到目标范围。",
      "description_en": "Wait until the device temperature reaches the target range."
    },
    {
      "action_name": "auto-number_of_connected_units",
      "description": "获取堆叠系统中已连接单元的数量。",
      "description_en": "Get the number of connected units in the stack."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取当前测得温度。",
      "description_en": "Get the current measured temperature."
    }
  ]
}

